engine=r'''
const spec=SPEC;
const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');
const fx=document.createElement('canvas');fx.width=992;fx.height=572;const fc=fx.getContext('2d');
const layer=document.createElement('canvas');layer.width=992;layer.height=572;const lc=layer.getContext('2d');
const battle=new Image();battle.src='battlefield-display.png';
const clamp=x=>Math.max(0,Math.min(1,x));
let t=0,playing=true,loop=true,speed=1,last=performance.now(),background='grey',selection=0;
function point(h,u,inset){let span=h.endAngle-h.startAngle;if(h.clockwise&&span<0)span+=360;if(!h.clockwise&&span>0)span-=360;let angle=(h.startAngle+span*u)*Math.PI/180;let co=Math.cos(angle),si=Math.sin(angle),rx=h.radiusX*h.lengthScale,ry=h.radiusY*h.lengthScale;let nx=co/rx,ny=si/ry,n=Math.hypot(nx,ny);let x=rx*co-inset*nx/n,y=ry*si-inset*ny/n,rot=h.rotation*Math.PI/180;return [16+h.pivot[0]+x*Math.cos(rot)-y*Math.sin(rot),16+h.pivot[1]+x*Math.sin(rot)+y*Math.cos(rot)]}
function band(h,lo,hi,outer,inner){if(hi<=lo)return;let ps=[];for(let j=0;j<=128;j++){let v=j/128,u=lo+(hi-lo)*v;let taper=Math.sin(Math.PI*v)**.65;ps.push({u,width:h.thickness*taper})}lc.beginPath();for(let j=0;j<ps.length;j++){let p=ps[j],xy=point(h,p.u,p.width*outer);j?lc.lineTo(...xy):lc.moveTo(...xy)}for(let j=ps.length-1;j>=0;j--){let p=ps[j];lc.lineTo(...point(h,p.u,p.width*inner))}lc.closePath();lc.fillStyle='#FFFFFF';lc.fill()}
function pass(h,lo,hi,outer,inner,blur,alpha){lc.clearRect(0,0,992,572);lc.globalAlpha=1;band(h,lo,hi,outer,inner);fc.save();fc.globalAlpha=alpha;fc.filter=blur?`blur(${blur}px)`:'none';fc.drawImage(layer,0,0);fc.restore()}
function drawHit(h,age){if(age<=0||age>=h.duration)return;let head=clamp(age/h.sweep),tail=clamp((age-h.sweep-.025)/(h.duration-h.sweep-.025));let fade=clamp(age/.025)*Math.pow(1-clamp((age-h.sweep)/(h.duration-h.sweep)),1.25);
 pass(h,tail,head,0,1,9,.23*fade);pass(h,tail,head,0,.8,3,.18*fade);
 // Finite white blade volume: bright outer face fading radially into a transparent inner wake.
 lc.clearRect(0,0,992,572);for(let k=0;k<64;k++){let a=k/64,b=(k+1)/64,alpha=(.88*Math.exp(-(((a-.17)/.35)**2)))*(1-a)**.55;lc.globalAlpha=alpha;band(h,tail,head,Math.max(0,a-.006),Math.min(1,b+.006))}lc.globalAlpha=1;fc.save();fc.filter='blur(1.2px)';fc.globalAlpha=fade;fc.drawImage(layer,0,0);fc.restore();
 pass(h,tail,head,0,.045,.15,.95*fade);
}
function effect(time,only=0){fc.clearRect(0,0,992,572);if(only){let h=spec.hits[only-1];drawHit(h,time-spec.hitClipLead)}else for(let h of spec.hits)drawHit(h,time-h.start);return fx}
function duration(){return selection?spec.hitClipDuration:spec.duration}
function render(){ctx.fillStyle=background==='dark'?'#101E30':background==='green'?'#A5C9A0':'#DADFE3';ctx.fillRect(0,0,992,572);if(background==='battle'&&battle.complete&&battle.naturalWidth)ctx.drawImage(battle,0,0,992,572);ctx.drawImage(effect(t,selection),0,0);let n=selection?+(t>=spec.hitClipLead+spec.hits[selection-1].sweep):spec.hits.filter(h=>t>=h.emphasis).length;let frames=selection?30:96;document.querySelector('#play').textContent=playing?'일시정지':'재생';document.querySelector('#scrub').max=frames;document.querySelector('#scrub').value=Math.min(frames,Math.floor(t*60)+1);document.querySelector('#status').textContent=`${selection?'독립 '+selection+'타':n+' / 3타'} · ${t.toFixed(3)}s · 프레임 ${Math.min(frames,Math.floor(t*60)+1)} / ${frames}`;}
function tick(now){let dt=(now-last)/1000;last=now;if(playing){t+=dt*speed;if(t>=duration()){if(loop)t%=duration();else{t=duration();playing=false}}}render();requestAnimationFrame(tick)}
document.querySelector('#play').onclick=()=>playing=!playing;document.querySelector('#restart').onclick=()=>{t=0;last=performance.now();render()};document.querySelector('#loop').onchange=e=>loop=e.target.checked;document.querySelector('#speed').onchange=e=>speed=+e.target.value;document.querySelector('#bg').onchange=e=>{background=e.target.value;render()};document.querySelector('#hit').onchange=e=>{selection=+e.target.value;t=0;last=performance.now();render()};
function seekFrame(i){playing=false;t=Math.max(0,Math.min((selection?30:96)-1,i-1))/60;render()}
document.querySelector('#scrub').oninput=e=>seekFrame(+e.target.value);document.querySelector('#prev').onclick=()=>seekFrame(Math.min(selection?30:96,Math.floor(t*60)+1)-1);document.querySelector('#next').onclick=()=>seekFrame(Math.floor(t*60)+2);
window.demo={spec,effect,point,seek:x=>{playing=false;t=x;render()},seekFrame,state:()=>({t,playing,loop,speed,background,selection}),exportFrames:async()=>{playing=false;for(let group of ['combo','hit1','hit2','hit3']){let count=group==='combo'?96:30,only=group==='combo'?0:+group.slice(-1);for(let i=0;i<count;i++){let data=effect(i/60,only).toDataURL('image/png').split(',')[1];let r=await fetch('/save/'+group+'/frame-'+String(i).padStart(3,'0')+'.png',{method:'POST',body:data});if(!r.ok)throw Error(group+i)}}return '186 RGBA frames exported'}};
requestAnimationFrame(tick);
'''.replace('SPEC',json.dumps(spec))
